function minimumTotal(triangle: number[][]): number {
  const n = triangle.length;
  // dp[j] — минимальная сумма пути от клетки (i, j) до низа треугольника.
  // Начинаем с последней строки: от неё до низа путь — она сама.
  const dp: number[] = [...triangle[n - 1]];

  // Поднимаемся снизу вверх
  for (let i = n - 2; i >= 0; i--) {
    for (let j = 0; j <= i; j++) {
      // Из (i, j) идём в (i+1, j) или (i+1, j+1) — берём лучший.
      // dp[j] и dp[j + 1] ещё хранят значения для строки i + 1,
      // а dp[j] перезаписываем уже для строки i (слева направо — безопасно)
      dp[j] = triangle[i][j] + Math.min(dp[j], dp[j + 1]);
    }
  }

  // Вершина треугольника — ответ
  return dp[0];
}

// Время: O(n²) — каждая клетка треугольника обрабатывается один раз
// Память: O(n) — одна строка dp
